import{_ as p,r as a,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"可用异常 - October CMS - 3.x","titleTemplate":false,"description":"October CMS 开箱即用地提供了几种基本的异常类型。","frontmatter":{"subtitle":"October CMS 开箱即用地提供了几种基本的异常类型。"},"headers":[{"level":3,"title":"应用异常","slug":"应用异常","link":"#应用异常","children":[]},{"level":3,"title":"系统异常","slug":"系统异常","link":"#系统异常","children":[]},{"level":3,"title":"未找到异常","slug":"未找到异常","link":"#未找到异常","children":[]},{"level":3,"title":"验证异常","slug":"验证异常","link":"#验证异常","children":[]},{"level":3,"title":"AJAX 异常","slug":"ajax-异常","link":"#ajax-异常","children":[]},{"level":2,"title":"异常处理","slug":"异常处理","link":"#异常处理","children":[{"level":3,"title":"错误处理程序的放置位置","slug":"错误处理程序的放置位置","link":"#错误处理程序的放置位置","children":[]}]},{"level":2,"title":"HTTP 异常","slug":"http-异常","link":"#http-异常","children":[{"level":3,"title":"自定义错误页面","slug":"自定义错误页面","link":"#自定义错误页面","children":[]}]}],"relativePath":"3.x/zh-cn/extend/system/exceptions.md","filePath":"3.x/zh-cn/extend/system/exceptions.md"}'),r={name:"3.x/zh-cn/extend/system/exceptions.md"};function u(d,n,k,h,g,x){const e=a("pre-heading"),t=a("post-heading");return o(),c("div",null,[s(e),n[0]||(n[0]=l("h1",null,"可用异常",-1)),s(t),n[1]||(n[1]=i(`<h3 id="应用异常"><a href="#应用异常" class="header-anchor">#</a> 应用异常</h3><p><code>October\\Rain\\Exception\\ApplicationException</code> 类，别名为 <code>ApplicationException</code>，是最常见的异常类型，用于简单的应用条件失败时。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ApplicationException</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;You must be logged in to do that!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>错误消息将被简化，并且永远不会包含任何敏感信息，如 PHP 文件和行号。</p><h3 id="系统异常"><a href="#系统异常" class="header-anchor">#</a> 系统异常</h3><p><code>October\\Rain\\Exception\\SystemException</code> 类，别名为 <code>SystemException</code>，用于对系统运行至关重要的错误，并且始终会被记录。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">SystemException</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Unable to contact the mail server API&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>当抛出此异常时，将显示详细的错误消息，包括发生错误的文件和行号。</p><h3 id="未找到异常"><a href="#未找到异常" class="header-anchor">#</a> 未找到异常</h3><p><code>October\\Rain\\Exception\\NotFoundException</code> 类，别名为 <code>NotFoundException</code>，用于遇到缺少记录时的错误。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">NotFoundException</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Record not found&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>当抛出此异常时，标准响应将更改为显示最近的未找到页面，并添加 404 状态码。</p><h3 id="验证异常"><a href="#验证异常" class="header-anchor">#</a> 验证异常</h3><p><code>October\\Rain\\Exception\\ValidationException</code> 类，别名为 <code>ValidationException</code>，用于与表单提交和无效字段直接相关的错误。消息应包含一个包含字段和错误消息的数组。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ValidationException</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;username&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Sorry that username is already taken!&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>你也可以传递一个<a href="./../services/validation.html">验证服务</a>的实例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$validation</span> <span class="token operator">=</span> <span class="token class-name static-context">Validator</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$validation</span><span class="token operator">-&gt;</span><span class="token function">fails</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ValidationException</span><span class="token punctuation">(</span><span class="token variable">$validation</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>当抛出此异常时，<a href="./ajax.html">AJAX 框架</a>将以可用格式提供此信息，并聚焦到第一个无效字段。</p><h3 id="ajax-异常"><a href="#ajax-异常" class="header-anchor">#</a> AJAX 异常</h3><p><code>October\\Rain\\Exception\\AjaxException</code> 类，别名为 <code>AjaxException</code>，被视为&quot;智能错误&quot;，将返回 HTTP 代码 406。这使得它们可以像成功响应一样传递响应内容。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">AjaxException</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#flashMessages&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>当抛出此异常时，<a href="./ajax.html">AJAX 框架</a>将遵循标准错误工作流程，但也会刷新指定的局部视图。</p><h2 id="异常处理"><a href="#异常处理" class="header-anchor">#</a> 异常处理</h2><p>所有异常由 <code>October\\Rain\\Foundation\\Exception\\Handler</code> 类处理。此类包含两个方法：<code>report</code> 和 <code>render</code>，它们决定错误是否应被记录以及如何响应错误。</p><p>但是，如果需要，你可以使用 <code>App::error</code> 方法指定自定义处理程序。处理程序根据它们处理的异常的类型提示进行调用。例如，你可以创建一个仅处理 <code>RuntimeException</code> 实例的处理程序：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token class-name type-declaration">RuntimeException</span> <span class="token variable">$exception</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Handle the exception...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果异常处理程序返回一个响应，该响应将发送到浏览器，不会调用其他错误处理程序。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token class-name type-declaration">InvalidUserException</span> <span class="token variable">$exception</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Sorry! Something is wrong with this account!&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要监听 PHP 致命错误，你可以检查 Error 异常类型：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token class-name type-declaration">Error</span> <span class="token variable">$exception</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果你有多个异常处理程序，应按从最通用到最具体的顺序定义。因此，例如，处理所有 <code>Exception</code> 类型异常的处理程序应在自定义异常类型（如 <code>SystemException</code>）之前定义。</p><h3 id="错误处理程序的放置位置"><a href="#错误处理程序的放置位置" class="header-anchor">#</a> 错误处理程序的放置位置</h3><p>错误处理程序注册通常属于引导代码的范畴。换句话说，它们为你的应用程序准备好实际处理请求，通常需要在路由或控制器被实际调用之前执行。最常见的位置是<a href="./../extending.html">插件注册文件</a>的 <code>boot</code> 方法。或者，插件可以在插件目录中提供一个名为 <strong>init.php</strong> 的文件，你可以用它来放置错误处理程序注册。</p><h2 id="http-异常"><a href="#http-异常" class="header-anchor">#</a> HTTP 异常</h2><p>某些异常描述来自服务器的 HTTP 错误代码。例如，这可能是&quot;页面未找到&quot;错误（404）、&quot;未授权错误&quot;（401）或甚至是开发者生成的 500 错误。为了从应用程序的任何位置生成此类响应，使用以下方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">abort</span><span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>abort</code> 方法将立即引发一个异常，该异常将由异常处理程序渲染。你可以选择性地提供响应文本。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">abort</span><span class="token punctuation">(</span><span class="token number">403</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Unauthorized action.&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>此方法可以在请求生命周期的任何时候使用。还有一个配套的<a href="./../../markup/function/abort.html">用于中止请求的 Twig 过滤器</a>。</p><h3 id="自定义错误页面"><a href="#自定义错误页面" class="header-anchor">#</a> 自定义错误页面</h3><p>默认情况下，任何错误都将显示一个详细的错误页面，包含发生错误的文件内容、行号和堆栈跟踪。你可以通过在 <code>config/app.php</code> 脚本中将配置值 <code>debug</code> 设置为 <strong>false</strong> 并创建一个 URL 为 <code>/error</code> 的页面来显示自定义错误页面。</p>`,41))])}const f=p(r,[["render",u]]);export{v as __pageData,f as default};
